reschedule(id: string, leaseToken: number, runAt: number, now: number): boolean {
  if (!this.owns(id, leaseToken, now)) return this.refuse();
  const e = this.entries.get(id)!;
  e.job.runAt = runAt;
  delete e.leaseToken;
  delete e.leaseUntil;
  this.stats.rescheduled++;
  return true;
}

