// src/queue.ts
export class InMemoryJobQueue implements JobQueue {
  constructor(private readonly options: { agingMs?: number } = {}) {
    const a = options.agingMs;
    if (a !== undefined && !(Number.isFinite(a) && a > 0)) throw new RangeError("agingMs must be > 0");
  }
  private effective(e: Entry, now: number): number {
    const a = this.options.agingMs;
    if (a === undefined) return e.job.priority;
    return Math.max(0, e.job.priority - Math.floor((now - e.job.runAt) / a));
  }
  // in claim():
  //   .sort((x, y) => this.effective(x, now) - this.effective(y, now) || x.job.runAt - y.job.runAt || x.seq - y.seq)
}

// test/queue.test.ts
it("aging: a marketing job that waited agingMs competes with transactional ones, never ahead of priority 0", () => {
  const make = () => {
    const q = new InMemoryJobQueue({ agingMs: 60_000 });
    q.enqueue(job("m-old", 1, 0));
    q.enqueue(job("otp", 0, 59_000));
    return q;
  };
  expect(make().claim(59_000, 1, 1_000)[0]!.recordId).toBe("otp");   // waited 59 s: still priority 1
  expect(make().claim(60_000, 1, 1_000)[0]!.recordId).toBe("m-old"); // aged to 0, earlier runAt wins
  const q = new InMemoryJobQueue({ agingMs: 1 });
  q.enqueue(job("otp", 0, 1_000));
  q.enqueue(job("m-ancient", 1, 1_000));
  expect(q.claim(1_000_000, 1, 1_000)[0]!.recordId).toBe("otp"); // floor at 0: FIFO tie, not ahead
});
